/*
 * rdata.c - DOS data-segment (dseg) definitions for the faithful renderer port.
 *
 * Every initialized value below is transcribed from the disassembled original
 * data segment: reference/restunts/src/restunts/asm/dseg.asm (dseg base
 * linear address 0x3B770).  Zero-initialized state variables are sized from
 * the same file.  Duplicated tables were cross-checked against
 * reference/restunts/src/restunts/sdl/main.cpp and sdl/data3d.cpp.
 *
 * The TRACKOBJECT tables and off_3BE44 are generated by
 * tools/extract_dseg_tables.py (reproducible transcription; do not hand-edit).
 *
 * C types follow the extern declarations in frame.c / shape3d.c / math.c /
 * externs.h (Watcom 16-bit mapping: db=char/uint8_t, dw=int16_t/uint16_t,
 * dd=int32_t or pointer).  `far` is #defined empty by rport.h/externs.h.
 */
#include "rfbsize.h"
#include "externs.h"
#include "shape3d.h"
#include "shape2d.h"
#include "math.h"

/* Layout sanity: the DOS structs that contain no pointers must keep their
 * exact 16-bit packed sizes in this port. */
_Static_assert(sizeof(struct RECTANGLE) == 8, "RECTANGLE packed size");
_Static_assert(sizeof(struct VECTOR) == 6, "VECTOR packed size");
_Static_assert(sizeof(struct MATRIX) == 18, "MATRIX packed size");
_Static_assert(sizeof(struct GAMEINFO) == 26, "GAMEINFO packed size");
_Static_assert(sizeof(struct GAMESTATE) == 1120, "GAMESTATE packed size");

