/* Patch the pack(1)-misaligned shape pointer fields at startup. */
__attribute__((constructor)) static void rdata_fixup_trackobject_shapes(void)
{
	size_t i;
	for (i = 0; i < sizeof(trkObjectList) / sizeof(trkObjectList[0]); i++) {
		if (trkObjectList_shapeidx[i][0] >= 0)
			trkObjectList[i].ss_shapePtr = &game3dshapes[trkObjectList_shapeidx[i][0]];
		if (trkObjectList_shapeidx[i][1] >= 0)
			trkObjectList[i].ss_loShapePtr = &game3dshapes[trkObjectList_shapeidx[i][1]];
	}
	for (i = 0; i < sizeof(sceneshapes2) / sizeof(sceneshapes2[0]); i++) {
		if (sceneshapes2_shapeidx[i][0] >= 0)
			sceneshapes2[i].ss_shapePtr = &game3dshapes[sceneshapes2_shapeidx[i][0]];
		if (sceneshapes2_shapeidx[i][1] >= 0)
			sceneshapes2[i].ss_loShapePtr = &game3dshapes[sceneshapes2_shapeidx[i][1]];
	}
	for (i = 0; i < sizeof(sceneshapes3) / sizeof(sceneshapes3[0]); i++) {
		if (sceneshapes3_shapeidx[i][0] >= 0)
			sceneshapes3[i].ss_shapePtr = &game3dshapes[sceneshapes3_shapeidx[i][0]];
		if (sceneshapes3_shapeidx[i][1] >= 0)
			sceneshapes3[i].ss_loShapePtr = &game3dshapes[sceneshapes3_shapeidx[i][1]];
	}
}

