/* ------------------------------------------------------------------ */
/* sprite_clear_1_color -- native replacement for the video-driver           */
/* routine that fills the sprite1 clip window with a solid color.             */
/* Window convention (rblit.c): rows [sprite_top, sprite_height),             */
/* columns [sprite_left2, sprite_widthsum).                                   */
/*                                                                            */
/* [FIXED 2026-08-16] This clamped to 320x200 and used a stride of 320, both  */
/* hardcoded. At RFB_SCALE > 1 the framebuffer is larger than that, so the    */
/* sky and ground fills were clipped to a 320x200 corner and written with the */
/* wrong row length - which is why a scaled-up view showed a band of stale    */
/* pixels below the horizon. It is the framebuffer's own size that matters    */
/* here, not the original's screen size.                                      */
/* ------------------------------------------------------------------ */
extern struct SPRITE sprite1;     /* rblit.c */
extern uint8_t rfb_pixels[];      /* rblit.c */

void sprite_clear_1_color(uint8_t color)
{
	uint16_t y;
	uint16_t x0 = sprite1.sprite_left2;
	uint16_t x1 = sprite1.sprite_widthsum;
	uint16_t y1 = sprite1.sprite_height;
	if (x1 > RFB_VIEW_W) x1 = RFB_VIEW_W;
	if (y1 > RFB_VIEW_H) y1 = RFB_VIEW_H;
	for (y = sprite1.sprite_top; y < y1; y++) {
		if (x0 < x1)
			memset(&rfb_pixels[(uint32_t)y * RFB_VIEW_W + x0], color,
			       (size_t)(x1 - x0));
	}
}

/* dseg 0x4083C. Declared in externs.h and defined nowhere until Phase 7
 * needed it: the colour of the acceleration curve in the car picker.
 * restunts2 has it as `performGraphColor dw 0x0001`. */
int16_t performGraphColor = 1;
